import{_ as l,a0 as o,w as r,s as d,ao as i,I as a,a1 as p,A as t,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"借助 zope.interface 深入了解 Python 接口 | LCTT x X-CMD","titleTemplate":false,"description":"借助 zope.interface 深入了解 Python 接口 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"借助 zope.interface 深入了解 Python 接口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"借助 zope.interface 深入了解 Python 接口 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20190924 An advanced look at Python interfaces using zope.interface","title":"借助 zope.interface 深入了解 Python 接口","tag":"202001","desc":""},"relativePath":"202001/20190924 An advanced look at Python interfaces using zope.interface.md","filePath":"[post].md"}'),f={name:"202001/20190924 An advanced look at Python interfaces using zope.interface.md"};function u(c,s,h,g,k,y){const e=o("Link");return r(),d("div",null,[s[20]||(s[20]=i('<h1 id="借助-zope-interface-深入了解-python-接口" tabindex="-1">借助 zope.interface 深入了解 Python 接口 <a class="header-anchor" href="#借助-zope-interface-深入了解-python-接口" aria-label="Permalink to “借助 zope.interface 深入了解 Python 接口”">​</a></h1><blockquote><p>Zope.interface 可以帮助声明存在哪些接口，是由哪些对象提供的，以及如何查询这些信息。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/getting_started_with_python.png?itok=MFEKm3gl" alt="Snake charmer cartoon with a yellow snake and a blue snake" title="Snake charmer cartoon with a yellow snake and a blue snake"></p><p><code>zope.interface</code> 库可以克服 Python 接口设计中的歧义性。让我们来研究一下。</p><h3 id="隐式接口不是-python-之禅" tabindex="-1">隐式接口不是 Python 之禅 <a class="header-anchor" href="#隐式接口不是-python-之禅" aria-label="Permalink to “隐式接口不是 Python 之禅”">​</a></h3>',5)),a("p",null,[p(e,{href:"https://en.wikipedia.org/wiki/Zen_of_Python"},{default:t(()=>[...s[0]||(s[0]=[n("Python 之禅",-1)])]),_:1}),s[1]||(s[1]=n(" 很宽松，但是有点自相矛盾，以至于你可以用它来例证任何东西。让我们来思考其中最著名的原则之一：“显示胜于隐式”。",-1))]),s[21]||(s[21]=a("p",null,[n("传统上，在 Python 中会隐含的一件事是预期的接口。比如函数已经记录了它期望一个“类文件对象”或“序列”。但是什么是类文件对象呢？它支持 "),a("code",null,".writelines"),n("吗？"),a("code",null,".seek"),n(" 呢？什么是一个“序列”？是否支持步进切片，例如 "),a("code",null,"a[1:10:2]"),n("？")],-1)),s[22]||(s[22]=a("p",null,"最初，Python 的答案是所谓的“鸭子类型”，取自短语“如果它像鸭子一样行走，像鸭子一样嘎嘎叫，那么它可能就是鸭子”。换句话说，“试试看”，这可能是你能得到的最具隐式的表达。",-1)),a("p",null,[s[3]||(s[3]=n("为了使这些内容显式地表达出来，你需要一种方法来表达期望的接口。",-1)),p(e,{href:"http://zope.org"},{default:t(()=>[...s[2]||(s[2]=[n("Zope",-1)])]),_:1}),s[4]||(s[4]=n(" Web 框架是最早用 Python 编写的大型系统之一，它迫切需要这些东西来使代码明确呈现出来，例如，期望从“类似用户的对象”获得什么。",-1))]),s[23]||(s[23]=i(`<p><code>zope.interface</code> 由 Zope 开发，但作为单独的 Python 包发布。<code>Zope.interface</code> 可以帮助声明存在哪些接口，是由哪些对象提供的，以及如何查询这些信息。</p><p>想象编写一个简单的 2D 游戏，它需要各种东西来支持精灵界面（LCTT 译注：“<ruby>精灵<rt> Sprite</rt></ruby>”是指游戏面板中各个组件）。例如，表示一个边界框，但也要表示对象何时与一个框相交。与一些其他语言不同，在 Python 中，将属性访问作为公共接口一部分是一种常见的做法，而不是实现 getter 和 setter。边界框应该是一个属性，而不是一个方法。</p><p>呈现精灵列表的方法可能类似于：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def render_sprites(render_surface, sprites):</span></span>
<span class="line"><span>    &quot;&quot;&quot;</span></span>
<span class="line"><span>    sprites 应该是符合 Sprite 接口的对象列表：</span></span>
<span class="line"><span>    * 一个名为 &quot;bounding_box&quot; 的属性，包含了边界框</span></span>
<span class="line"><span>    * 一个名为 &quot;intersects&quot; 的方法，它接受一个边界框并返回 True 或 False</span></span>
<span class="line"><span>    &quot;&quot;&quot;</span></span>
<span class="line"><span>    pass # 一些做实际渲染的代码</span></span></code></pre></div><p>该游戏将具有许多处理精灵的函数。在每个函数中，你都必须在随附文档中指定预期。</p><p>此外，某些函数可能期望使用更复杂的精灵对象，例如具有 Z 序的对象。我们必须跟踪哪些方法需要 Sprite 对象，哪些方法需要 SpriteWithZ 对象。</p><p>如果能够使精灵是显式而直观的，这样方法就可以声明“我需要一个精灵”，并有个严格定义的接口，这不是很好吗？来看看 <code>zope.interface</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope import interface</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class ISprite(interface.Interface):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    bounding_box = interface.Attribute(</span></span>
<span class="line"><span>        &quot;边界框&quot;</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def intersects(box):</span></span>
<span class="line"><span>        &quot;它和一个框相交吗？&quot;</span></span></code></pre></div><p>乍看起来，这段代码有点奇怪。这些方法不包括 <code>self</code>，而包含 <code>self</code> 是一种常见的做法，并且它有一个<strong>属性</strong>。这是在 <code>zope.interface</code> 中声明接口的方法。这看起来很奇怪，因为大多数人不习惯严格声明接口。</p><p>这样做的原因是接口显示了如何调用方法，而不是如何定义方法。因为接口不是超类，所以它们可以用来声明数据属性。</p><p>下面是一个能带有圆形精灵的接口的一个实现：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@implementer(ISprite)</span></span>
<span class="line"><span>@attr.s(auto_attribs=True)</span></span>
<span class="line"><span>class CircleSprite:</span></span>
<span class="line"><span>    x: float</span></span>
<span class="line"><span>    y: float</span></span>
<span class="line"><span>    radius: float</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @property</span></span>
<span class="line"><span>    def bounding_box(self):</span></span>
<span class="line"><span>        return (</span></span>
<span class="line"><span>            self.x - self.radius,</span></span>
<span class="line"><span>            self.y - self.radius,</span></span>
<span class="line"><span>            self.x + self.radius,</span></span>
<span class="line"><span>            self.y + self.radius,</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def intersects(self, box):</span></span>
<span class="line"><span>        # 当且仅当至少一个角在圆内时，方框与圆相交</span></span>
<span class="line"><span>        top_left, bottom_right = box[:2], box[2:]</span></span>
<span class="line"><span>        for choose_x_from (top_left, bottom_right):</span></span>
<span class="line"><span>            for choose_y_from (top_left, bottom_right):</span></span>
<span class="line"><span>                x = choose_x_from[0]</span></span>
<span class="line"><span>                y = choose_y_from[1]</span></span>
<span class="line"><span>                if (((x - self.x) \` 2 + (y - self.y) \` 2) &amp;lt;=</span></span>
<span class="line"><span>                    self.radius \` 2):</span></span>
<span class="line"><span>                     return True</span></span>
<span class="line"><span>        return False</span></span></code></pre></div><p>这<strong>显式</strong>声明了实现了该接口的 <code>CircleSprite</code> 类。它甚至能让我们验证该类是否正确实现了接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope.interface import verify</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def test_implementation():</span></span>
<span class="line"><span>    sprite = CircleSprite(x=0, y=0, radius=1)</span></span>
<span class="line"><span>    verify.verifyObject(ISprite, sprite)</span></span></code></pre></div><p>这可以由 pytest、nose 或其他测试框架运行，它将验证创建的精灵是否符合接口。测试通常是局部的：它不会测试仅在文档中提及的内容，甚至不会测试方法是否可以在没有异常的情况下被调用！但是，它会检查是否存在正确的方法和属性。这是对单元测试套件一个很好的补充，至少可以防止简单的拼写错误通过测试。</p><hr>`,16)),a("p",null,[s[6]||(s[6]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/19/9/zopeinterface-python-package"},{default:t(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/19/9/zopeinterface-python-package",-1)])]),_:1})]),a("p",null,[s[11]||(s[11]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[7]||(s[7]=[n("Moshe Zadka",-1)])]),_:1}),s[12]||(s[12]=n(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),p(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[9]||(s[9]=[n("MjSeven",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const T=l(f,[["render",u]]);export{x as __pageData,T as default};
